import type { BeatGrid, GridPoint, MeterChange, ShowCue, SongVariant, TrackMeta } from 'shared-types'
import { formatTimeTag } from './chordpro'
import { formatBarDirective } from './partStart'

/**
 * The Rig-Check test song (#464, docs/24 §4): generated by the app, so every beat, section, cue
 * and alert time is known - the ground truth the whole rig and the timeline analysis are checked
 * against. Two runs: the quick check at every soundcheck (~45 s) and the full run after a new
 * setup (~2½ min).
 *
 * Tempo follows the app's own grid (lib/beatGrid.ts): constant between alignment points, and a
 * gradual stretch (#354) changes the beat *spacing* evenly from beat to beat - so the app's click
 * grid must land on every generated beat. The one deliberate exception is a tempo change inside a
 * bar: grid points sit only at bar starts, which the full run shows on purpose.
 *
 * Bump RIG_CHECK_VERSION whenever the song or its sound changes: the track id carries it, so the
 * next Vorbereiten replaces the uploaded track.
 */
export const RIG_CHECK_VERSION = 1

export type RigCheckKind = 'quick' | 'full'

/** Fixed ids of the hidden Rig-Check docs (docs/24 §5) - never in the Bibliothek or a picker. */
export const RIG_CHECK_SONG_ID = 'rig-check'
export const RIG_CHECK_SETLIST_ID = 'rig-check'
export const rigCheckVariantId = (kind: RigCheckKind) => `rig-check-${kind}`
export const RIG_CHECK_TRACK_ID = `rig-check-v${RIG_CHECK_VERSION}`

/** Whether a song or setlist id is the hidden Rig-Check one. */
export function isRigCheckId(id: string): boolean {
  return id === RIG_CHECK_SONG_ID || id === RIG_CHECK_SETLIST_ID
}

export interface RigCheckSection {
  name: string
  /** The part's name on screen - and what a section jump targets. */
  label: string
  bars: number
  timeSignature: string
  /** Tempo at the start of the section. */
  bpm: number
  /** Tempo at the end: the spacing changes evenly over the section (ritardando/accelerando). */
  endBpm?: number
  /** A tempo change inside the section's first bar, from this beat (0-based) on. */
  changeInBar?: { beat: number; bpm: number }
  /** No sound - a rest of the whole band (the click and the grid go on). */
  silent?: boolean
  /** The master jumps over this section (#479) - nobody should ever hear or see it. */
  skipped?: boolean
}

/** Quick check (Marco, 2026-10-26): count-in, 8 bars at 120, a jump, 4 bars at 140. */
export const QUICK_SECTIONS: RigCheckSection[] = [
  { name: 'steady', label: 'Gleichmäßig 120', bars: 8, timeSignature: '4/4', bpm: 120 },
  { name: 'skipped', label: 'Übersprungen', bars: 4, timeSignature: '4/4', bpm: 120, skipped: true },
  { name: 'jump', label: 'Sprung 140', bars: 4, timeSignature: '4/4', bpm: 140 },
  { name: 'ending', label: 'Schluss', bars: 1, timeSignature: '4/4', bpm: 140 },
]

/** Full run: the reference song of 2026-10-09 (#464) plus a skipped section for the jump. */
export const FULL_SECTIONS: RigCheckSection[] = [
  { name: 'steady', label: 'Gleichmäßig 120', bars: 16, timeSignature: '4/4', bpm: 120 },
  { name: 'ritardando', label: 'Ritardando 120 → 90', bars: 8, timeSignature: '4/4', bpm: 120, endBpm: 90 },
  { name: 'slow', label: 'Gleichmäßig 90', bars: 4, timeSignature: '4/4', bpm: 90 },
  { name: 'jump', label: 'Sprung auf 140', bars: 8, timeSignature: '4/4', bpm: 140 },
  { name: 'change-in-bar', label: 'Wechsel im Takt → 100', bars: 6, timeSignature: '4/4', bpm: 140, changeInBar: { beat: 2, bpm: 100 } },
  { name: 'three-four', label: 'Dreiviertel 100', bars: 6, timeSignature: '3/4', bpm: 100 },
  { name: 'skipped', label: 'Übersprungen', bars: 4, timeSignature: '3/4', bpm: 100, skipped: true },
  { name: 'rest', label: 'Pause', bars: 2, timeSignature: '4/4', bpm: 120, silent: true },
  { name: 'reentry', label: 'Wiedereinstieg 120', bars: 8, timeSignature: '4/4', bpm: 120 },
  { name: 'ending', label: 'Schluss', bars: 4, timeSignature: '4/4', bpm: 120 },
]

/** Silence before bar 1 - one bar of count-in at 120 fits exactly (the app clicks it). */
export const RIG_CHECK_LEAD_IN_MS = 2000
/** Silence after the last beat, so the last beep rings out before the track ends. */
const TAIL_MS = 1500

export interface RigCheckBeat {
  /** 1-based bar, as in the app's grid. */
  bar: number
  /** 0-based beat in the bar. */
  beat: number
  timeMs: number
  /** Tempo of the spacing to the next beat. */
  bpm: number
  section: string
  silent: boolean
  /** Pitch of this beat's beep (one per bar, 300-840 Hz - at least 160 Hz clear of the click's
   * 1000/1500 Hz, so a filter separates them even when both sound at the same moment). */
  pitchHz: number
}

export interface RigCheckSong {
  kind: RigCheckKind
  title: string
  bpm: number
  timeSignature: string
  durationMs: number
  beats: RigCheckBeat[]
  /** Section starts: bar and time. */
  sections: { name: string; label: string; bar: number; timeMs: number; bars: number; skipped: boolean }[]
  grid: BeatGrid
  /** Bars whose beats the grid cannot place exactly (a tempo change inside the bar). */
  approximateBars: number[]
  /** The jump the master queues at start: at the end of `from`, on to `to` (both part labels). */
  jump: { from: string; to: string }
  /** When the device cues go out (song time). */
  cueTimesMs: number[]
  /** `{alert:}` flashes at known times. */
  alerts: { timeMs: number; text: string }[]
  chordPro: string
}

const beatsPerBar = (timeSignature: string) => Number(timeSignature.split('/')[0]) || 4
export const BEEP_PITCHES_HZ = Array.from({ length: 10 }, (_, i) => 300 + 60 * i)
export const beepPitchHz = (bar: number) => BEEP_PITCHES_HZ[(bar - 1) % 10]!

export const SKIPPED_TEXT = 'Hier falsch – Sprung fehlgeschlagen'

export function buildRigCheckSong(kind: RigCheckKind, leadInMs = RIG_CHECK_LEAD_IN_MS): RigCheckSong {
  const sections = kind === 'quick' ? QUICK_SECTIONS : FULL_SECTIONS
  const beats: RigCheckBeat[] = []
  const sectionStarts: RigCheckSong['sections'] = []
  const points: GridPoint[] = []
  const meters: MeterChange[] = []
  const approximateBars: number[] = []
  let t = leadInMs
  let bar = 1
  let meter = sections[0]!.timeSignature

  for (const s of sections) {
    const perBar = beatsPerBar(s.timeSignature)
    const n = s.bars * perBar
    const p0 = 60000 / s.bpm
    const p1 = 60000 / (s.endBpm ?? s.bpm)
    sectionStarts.push({ name: s.name, label: s.label, bar, timeMs: t, bars: s.bars, skipped: s.skipped === true })
    points.push({ id: `rig-${s.name}`, bar, timeMs: Math.round(t), ...(s.endBpm !== undefined ? { gradual: true } : {}) })
    if (s.timeSignature !== meter) {
      meters.push({ bar, timeSignature: s.timeSignature })
      meter = s.timeSignature
    }
    if (s.changeInBar) approximateBars.push(bar)
    for (let x = 0; x < n; x++) {
      // Spacing of this beat: an even change over a gradual section (the app's p0 + (p1-p0)·x/N),
      // or the in-bar change from its beat on.
      let period = p0 + ((p1 - p0) * x) / n
      if (s.changeInBar && x >= s.changeInBar.beat) period = 60000 / s.changeInBar.bpm
      const b = bar + Math.floor(x / perBar)
      beats.push({ bar: b, beat: x % perBar, timeMs: t, bpm: 60000 / period, section: s.name, silent: s.silent === true, pitchHz: beepPitchHz(b) })
      // Exact integral of the linear spacing: t advances by the mean of this beat's start and end spacing.
      const next = s.changeInBar && x + 1 >= s.changeInBar.beat ? period : p0 + ((p1 - p0) * (x + 1)) / n
      t += s.endBpm !== undefined ? (period + next) / 2 : period
    }
    if (s.changeInBar && s.bars > 1) {
      // A point at the next bar keeps the in-bar change's error to that one bar.
      const next = beats.find((x) => x.bar === bar + 1 && x.beat === 0)!
      points.push({ id: `rig-${s.name}-2`, bar: bar + 1, timeMs: Math.round(next.timeMs) })
    }
    bar += s.bars
  }
  // The point after the last bar closes the last stretch (and a gradual one before it).
  points.push({ id: 'rig-end', bar, timeMs: Math.round(t) })

  const at = (name: string) => sectionStarts.find((s) => s.name === name)!
  const beatTime = (b: number, beat = 0) => beats.find((x) => x.bar === b && x.beat === beat)!.timeMs
  const skipped = at('skipped')
  const before = sectionStarts[sectionStarts.indexOf(skipped) - 1]!
  const after = sectionStarts[sectionStarts.indexOf(skipped) + 1]!

  const cueTimesMs =
    kind === 'quick'
      ? [beatTime(at('steady').bar + 4)]
      : [beatTime(at('steady').bar + 8), at('ritardando').timeMs, at('jump').timeMs, at('reentry').timeMs]
  const alerts =
    kind === 'quick'
      ? [{ timeMs: cueTimesMs[0]!, text: 'Takt 5: Cue an die Geräte' }]
      : [
          { timeMs: beatTime(at('ritardando').bar - 2), text: 'Ritardando in 2 Takten' },
          { timeMs: beatTime(before.bar + before.bars - 1), text: 'Nach diesem Takt: Sprung zur Pause' },
        ]
  // A flash nobody should ever see: it only shows when the jump failed.
  alerts.push({ timeMs: skipped.timeMs, text: SKIPPED_TEXT })
  alerts.sort((a, b) => a.timeMs - b.timeMs)

  const title = kind === 'quick' ? 'Rig-Check · Kurz' : 'Rig-Check · Voll'
  // No `{title:}` line: the prompter would count it as a line of a part before the first one.
  const lines: string[] = []
  for (const s of sectionStarts) {
    lines.push(`{part: ${s.label}}`, formatBarDirective(s.bar))
    for (let i = 0; i < s.bars; i++) {
      const b = s.bar + i
      for (const alert of alerts) if (Math.abs(alert.timeMs - beatTime(b)) < 1) lines.push(`${formatTimeTag(alert.timeMs)} {alert: ${alert.text}}`)
      lines.push(`${formatTimeTag(beatTime(b))} Takt ${b} · ${s.skipped ? SKIPPED_TEXT : s.label}`)
    }
    lines.push('')
  }

  return {
    kind,
    title,
    bpm: sections[0]!.bpm,
    timeSignature: sections[0]!.timeSignature,
    durationMs: Math.round(t + TAIL_MS),
    beats,
    sections: sectionStarts,
    grid: { points, meters },
    approximateBars,
    jump: { from: before.label, to: after.label },
    cueTimesMs: cueTimesMs.map(Math.round),
    alerts,
    chordPro: lines.join('\n'),
  }
}

/** A device command chosen for the Rig-Check (docs/24 §3): what a device gets at each cue time. */
export interface RigCheckDeviceCue {
  targetLogicalDeviceId: string
  type: string
  payload: Record<string, unknown>
}

/** The device cues at the song's cue times - the same id on every device, so a re-prepare keeps
 * the Nachbericht's cue entries comparable. */
export function rigCheckCues(song: RigCheckSong, deviceCues: readonly RigCheckDeviceCue[]): ShowCue[] {
  return song.cueTimesMs.flatMap((timeMs, slot) =>
    deviceCues.map((cue) => ({
      id: `rig-check-cue-${slot + 1}-${cue.targetLogicalDeviceId}`,
      timeMs,
      targetLogicalDeviceId: cue.targetLogicalDeviceId,
      type: cue.type,
      payload: cue.payload,
    })),
  )
}

/** The variant the Gig plays: grid, text, cues, count-in and click on, the generated track. */
export function rigCheckVariant(song: RigCheckSong, cues: ShowCue[], tracks: TrackMeta[]): SongVariant {
  return {
    id: rigCheckVariantId(song.kind),
    songId: RIG_CHECK_SONG_ID,
    label: song.kind === 'quick' ? 'Kurz' : 'Voll',
    isDefault: song.kind === 'quick',
    bpm: song.bpm,
    timeSignature: song.timeSignature,
    clickTrackEnabled: true,
    chordProContent: song.chordPro,
    timecodes: [],
    tracks,
    beatGrid: song.grid,
    cues,
    countInEnabled: true,
    countInBars: 1,
    durationMs: song.durationMs,
  }
}

function addTone(out: Float32Array, sampleRate: number, timeMs: number, ms: number, sample: (s: number) => number) {
  const start = Math.round((timeMs / 1000) * sampleRate)
  const len = Math.round((ms / 1000) * sampleRate)
  for (let i = 0; i < len && start + i < out.length; i++) out[start + i] += sample(i / sampleRate)
}

/** "Beeps": a short sine beep on every beat, its pitch telling the bar - for measuring. */
export function synthesizeBeeps(song: RigCheckSong, sampleRate = 44100): Float32Array {
  const out = new Float32Array(Math.ceil((song.durationMs / 1000) * sampleRate))
  for (const b of song.beats) {
    if (b.silent) continue
    const amp = b.beat === 0 ? 0.7 : 0.45
    // 1 ms rise - a sharp, unambiguous onset - then a quick decay.
    addTone(out, sampleRate, b.timeMs, 40, (s) => amp * Math.min(1, s / 0.001) * Math.exp(-s / 0.008) * Math.sin(2 * Math.PI * b.pitchHz * s))
  }
  return out
}

/** "Drums": kick on 1 (and 3 in 4/4), snare on the other beats, hi-hat eighths - for tempo detection. */
export function synthesizeDrums(song: RigCheckSong, sampleRate = 44100): Float32Array {
  const out = new Float32Array(Math.ceil((song.durationMs / 1000) * sampleRate))
  let seed = 1
  const noise = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 0xffffffff) * 2 - 1
  const kick = (t: number) => addTone(out, sampleRate, t, 180, (s) => 0.9 * Math.exp(-s / 0.05) * Math.sin(2 * Math.PI * (50 * s + 70 * (1 - Math.exp(-s / 0.03)) * 0.03)))
  const snare = (t: number) => addTone(out, sampleRate, t, 150, (s) => 0.5 * Math.exp(-s / 0.04) * (0.7 * noise() + 0.3 * Math.sin(2 * Math.PI * 190 * s)))
  let prevHat = 0
  const hat = (t: number, amp: number) =>
    addTone(out, sampleRate, t, 40, (s) => {
      const n = noise()
      const high = n - prevHat // a crude high-pass
      prevHat = n
      return amp * Math.exp(-s / 0.012) * high
    })
  const meterAt = (bar: number) => {
    let meter = song.timeSignature
    for (const m of song.grid.meters) if (m.bar <= bar) meter = m.timeSignature
    return meter
  }
  for (let i = 0; i < song.beats.length; i++) {
    const b = song.beats[i]!
    if (b.silent) continue
    const perBar = beatsPerBar(meterAt(b.bar))
    if (b.beat === 0 || (perBar === 4 && b.beat === 2)) kick(b.timeMs)
    else snare(b.timeMs)
    hat(b.timeMs, 0.25)
    const next = song.beats[i + 1]
    if (next) hat((b.timeMs + next.timeMs) / 2, 0.15)
  }
  return out
}

/** The track the master uploads: beeps over drums, peak-normalized below full scale. */
export function synthesizeRigCheckTrack(song: RigCheckSong, sampleRate = 44100): Float32Array {
  const out = synthesizeBeeps(song, sampleRate)
  const drums = synthesizeDrums(song, sampleRate)
  let peak = 0
  for (let i = 0; i < out.length; i++) {
    out[i] = out[i]! + 0.6 * drums[i]!
    peak = Math.max(peak, Math.abs(out[i]!))
  }
  const gain = peak > 0.9 ? 0.9 / peak : 1
  if (gain !== 1) for (let i = 0; i < out.length; i++) out[i] = out[i]! * gain
  return out
}

/** 16-bit mono PCM WAV. */
export function encodeWav(samples: Float32Array, sampleRate = 44100): Uint8Array {
  const data = new DataView(new ArrayBuffer(44 + samples.length * 2))
  const text = (offset: number, s: string) => [...s].forEach((c, i) => data.setUint8(offset + i, c.charCodeAt(0)))
  text(0, 'RIFF')
  data.setUint32(4, 36 + samples.length * 2, true)
  text(8, 'WAVE')
  text(12, 'fmt ')
  data.setUint32(16, 16, true)
  data.setUint16(20, 1, true) // PCM
  data.setUint16(22, 1, true) // mono
  data.setUint32(24, sampleRate, true)
  data.setUint32(28, sampleRate * 2, true)
  data.setUint16(32, 2, true)
  data.setUint16(34, 16, true)
  text(36, 'data')
  data.setUint32(40, samples.length * 2, true)
  for (let i = 0; i < samples.length; i++) data.setInt16(44 + i * 2, Math.round(Math.max(-1, Math.min(1, samples[i]!)) * 32767), true)
  return new Uint8Array(data.buffer)
}
